    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Horizontal bars encode a missing border row in the small stripe case.
    full_rows = []
    for r, row in enumerate(grid):
        if row[0] != 0 and all(v == row[0] for v in row):
            full_rows.append((r, row[0]))
    if full_rows and all(all(v == 0 for v in row) or (row[0] != 0 and all(v == row[0] for v in row)) for row in grid):
        for r, row in enumerate(grid):
            if all(v == 0 for v in row):
                out[r] = [full_rows[-1][1]] * w
        return out

    # Colored diagonals identify one color for each residue of a repeating pattern.
    diagonal_color = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                diagonal_color.setdefault(c - r, value)
    period = len(diagonal_color)
    residue_color = {d % period: color for d, color in diagonal_color.items()}
    return [[residue_color[(c - r) % period] for c in range(w)] for r in range(h)]
